const course: DeepCourse = {"slug":"complete-va-starter","title":"The Complete VA Starter.","premium":false,"previewCount":3,"chunks":[{"kind":"html","value":"<section class=\"px-5 pt-28 md:px-8 md:pt-40\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Foundations · free</p><h1 class=\"display-lg mt-4\">The Complete VA Starter<span class=\"dot\" aria-hidden=\"true\">.</span></h1><p class=\"lede mt-5 max-w-xl\">From an empty desk to a signed client and a paid invoice, without the guru nonsense in between.</p><div class=\"mt-8\"><div class=\"flex flex-wrap items-center gap-2.5\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free course</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">10 modules</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">4h 45m of reading and doing</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">8 portfolio pieces</span></div><p class=\"mt-4 mb-2 text-[0.8125rem] text-muted\">Course content is based on active job listings and industry hiring patterns. These are practical guides, not formal certifications.</p></div></div></section><nav aria-label=\"Course sections\" class=\"sticky top-16 z-20 border-b border-line bg-paper/90 backdrop-blur-md\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-6xl\"><ul class=\"-mx-1 flex gap-1 overflow-x-auto py-2.5 [scrollbar-width:none] [&amp;::-webkit-scrollbar]:hidden\"><li><a href=\"#the-job\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">The job</a></li><li><a href=\"#tools\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Tools</a></li><li><a href=\"#modules\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Modules</a></li><li><a href=\"#rates\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Rates</a></li><li><a href=\"#first-client\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">First client</a></li><li><a href=\"#quiz\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Quiz</a></li><li><a href=\"#glossary\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Glossary</a></li><li><a href=\"#red-flags\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Red flags</a></li><li><a href=\"#faq\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">FAQ</a></li></ul></div></nav><section class=\"px-5 pt-10 md:px-8\"><div class=\"mx-auto max-w-5xl\"><div id=\"plain-words\" class=\"rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><p class=\"eyebrow\">In plain words</p><p class=\"mt-3 max-w-3xl text-[1.0625rem] leading-[1.75] text-ink\">This is the start-from-zero course. It takes you from ‘I have a laptop and I need income’ to your first paying client — setting up your tools, finding real jobs, applying properly, and not getting scammed along the way.</p><div class=\"mt-6 grid gap-5 sm:grid-cols-2\"><div><p class=\"eyebrow text-muted\">This is for you if</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">You’ve never freelanced before, or you started but nothing is landing yet. No experience needed — that’s the point.</p></div><div><p class=\"eyebrow text-muted\">You walk away with</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">A working setup, a starter portfolio, a rate you can defend, and a step-by-step plan for your first 30 days.</p></div></div></div></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"the-job\" class=\"scroll-mt-32\"><div class=\"space-y-5\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">Most &quot;become a VA&quot; advice is a list of tools and a promise. This track is the boring version that actually works: build a setup that does not fail, pick one lane, learn the four habits every client silently grades you on, and get paid without losing a chunk of it to fees.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">The uncomfortable part first. &quot;Virtual assistant&quot; is not a job, it is a category. Clients hire a person who does a specific thing for a specific kind of business. A Filipino VA on r/buhaydigital said it plainly to someone getting no replies: &quot;One mistake that every beginner does is they are all applying as a &#x27;VA&#x27;. You have almost zero chance when you do this.&quot; Module 4 is where you fix that.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">You will practise on one fictional first client: Dee Whitlock, who runs Sortly Home, a two-person home-organising business in Portland. She is disorganised, generous, and slightly chaotic, which makes her exactly like a real first client. By module 10 you will have a proof folder, a rate, a contract, an invoice, and a 30-day plan.</p></div><dl class=\"mt-10 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card shadow-tile\"><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Who this is for</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Zero experience, career shifters, BPO leavers, anyone starting cold</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">What you end with</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">A proof folder, one narrow offer, a rate, and a paid-invoice workflow</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Realistic timeline</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">4 to 12 weeks to a first client if you apply properly, longer if you apply as &#x27;a VA&#x27;</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Starting money</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Under ₱3,000 if you already own a laptop. Almost every tool has a free tier</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Hardest part</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Nobody tells you when you are ready. You just start before you feel it</dd></div></dl></section><section class=\"mt-16\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What a shift actually looks like</h2><ol class=\"mt-6 space-y-0\"><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Before shift</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Power and connection check</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Speed test, charge the backup, confirm the mobile data has load. Two minutes that save your job.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">First 15 minutes</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Read the channels before you touch anything</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Slack, email, the task board. Find out what changed while you were asleep, then plan.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Morning block</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">The client&#x27;s actual work</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">One task at a time, timer running, questions batched instead of pinged one by one.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Midday</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Questions and confirmations</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">One message with three numbered questions beats three messages an hour apart.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Afternoon block</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Deep work and documentation</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Every repeated task becomes a line in an SOP while you are doing it, not later.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">End of shift</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">The update nobody asked for</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Done, blocked, next. Four lines. This single habit is why clients keep beginners.</p></div></li></ol></section></div><section id=\"tools\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">The tools, and why each one exists</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Do not buy anything yet. Learn the free ones properly and use the client&#x27;s licence for the rest — that is what everyone else is doing too.</p><div class=\"mt-8 space-y-8\"><div><p class=\"eyebrow text-muted\">The starter stack, all free to begin</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Workspace (personal)</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Gmail, Calendar, Drive, Docs, Sheets. Ninety percent of VA work happens here.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Slack</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Where most small teams talk. Learn threads, mentions, saved items, and DND.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Trello or Notion</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">One task board so nothing lives only in your head or in a chat message.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Loom</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Screen recordings for handoffs and portfolio walkthroughs. Enormous leverage for shy people.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Canva</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Not just graphics. Fast, clean one-page documents for proposals and reports.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Toggl Track</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Your own time log, separate from any client tracker. Tells you what you actually earn per hour.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Bitwarden</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Password manager. Sharing passwords in chat is a hiring red flag on both sides.</p></li></ul></div><div><p class=\"eyebrow text-muted\">Money and paperwork</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Wise</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Cheapest way to receive USD, EUR or GBP directly from a client&#x27;s bank, then convert to PHP.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Payoneer</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Best when the client pays through a platform, or wants to send to a US-style account.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">PayPal</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Convenient and widely accepted. Also the most expensive once the FX markup is counted.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">GCash or a digital bank</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">For local spending once the money lands. Keep work money in a separate account.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Sheets invoice template</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">You do not need invoicing software in year one. You need a consistent numbered invoice.</p></li></ul></div><div><p class=\"eyebrow text-muted\">Reliability gear, in order of what to buy first</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Backup mobile data</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">A registered SIM with load and hotspot enabled. Cheapest insurance you will ever buy.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">UPS or a power bank for the router</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Keeps you online through a short brownout so a meeting does not just end.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Wired headset with a mic</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Audio quality is judged more harshly than video. Laptop mics sound like a tunnel.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Ethernet cable</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Free stability. Wi-Fi is the reason half of &quot;my internet is bad&quot; actually happens.</p></li></ul></div></div></div></section>"},{"kind":"slot","value":"MODULES","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"keep-learning\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Keep learning<span class=\"dot\" aria-hidden=\"true\">.</span></h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Hand-picked and free. These open in a new tab — official docs, academies and channels that go deeper on what this track teaches. No affiliate links, no sign-up walls.</p><ul class=\"mt-8 grid gap-3 sm:grid-cols-2\"><li class=\"h-full\"><a href=\"https://support.google.com/a/users/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Workspace Learning Center</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Gmail, Docs, Sheets, Calendar — the tools in almost every VA job ad, taught by Google.</p></a></li><li class=\"h-full\"><a href=\"https://www.canva.com/designschool/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Canva Design School</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Free structured lessons for the design tasks clients hand to general VAs.</p></a></li><li class=\"h-full\"><a href=\"https://www.loom.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Loom</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Record your screen with your voice over it. The fastest way to prove you can do a task.</p></a></li><li class=\"h-full\"><a href=\"https://www.notion.com/help\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Notion Help &amp; Academy</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Docs, wikis and databases — learn it before a client asks if you know it.</p></a></li><li class=\"h-full\"><a href=\"https://www.worldtimebuddy.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">World Time Buddy</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Never propose a meeting at 3am their time. Pin your client cities.</p></a></li><li class=\"h-full\"><a href=\"https://hemingwayapp.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Hemingway Editor</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Paste your message, fix everything highlighted red. Free and instant.</p></a></li></ul></section></div>"},{"kind":"html","value":"<section class=\"border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><section id=\"rates\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What this actually pays</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">General VA benchmarks from the OnlineJobs.ph April 2026 salary guide. Beginners start at the bottom of this and move quickly if they specialise. Treat these as what is being paid in the market, not a ceiling and not a verdict on your worth.</p><div class=\"mt-7 rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><div class=\"space-y-7\"><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Beginner</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">3–5<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:25%;width:16.666666666666664%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">General admin and data work, supervised, single client.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 480–800/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Intermediate</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">6–9<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:50%;width:25%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Owns a workflow end to end. Client stops checking your output.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 960–1,440/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Expert</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">10–12<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:83.33333333333334%;width:16.666666666666664%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Specialist skill or a lane with real business impact. Referrals come to you.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 1,600–1,920/mo full-time</p></div></div></div><p class=\"mt-7 border-t border-line pt-4 text-[0.75rem] leading-relaxed text-muted-2\">Directional market benchmarks, not a guarantee and not a ceiling. Source: <a href=\"https://blog.onlinejobs.ph/comprehensive-guide-to-virtual-assistant-salaries-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">OnlineJobs.ph salary guide, April 2026</a>. Monthly figures assume 40 hours a week, which most VA roles are not.</p></div><div class=\"mt-5 rounded-2xl border border-[#f4d9c6] bg-clay-wash/70 p-6 sm:p-7\"><p class=\"eyebrow text-clay-deep\">What actually moves you up a band</p><ul class=\"mt-3.5 grid gap-2.5 sm:grid-cols-2\"><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You picked one lane and your samples all point the same direction</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You send a status update without being asked, every single day</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You write the SOP for the thing you were hired to do</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You never go dark during an outage</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You can be handed a vague request and return a plan instead of questions</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You have a second client, so no single client controls your income</li></ul></div></section></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><figure class=\"rounded-2xl border border-line bg-card p-7 shadow-card sm:p-9\"><figcaption class=\"flex flex-wrap items-center gap-3\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">Worker story</span><span class=\"text-[0.8125rem] text-muted\">One person&#x27;s experience, not a universal rule</span></figcaption><h2 class=\"mt-4 font-display text-[1.5rem] font-semibold leading-snug text-ink\">The VA who treated brownouts as a business expense</h2><blockquote class=\"mt-5 border-l-2 border-clay pl-5 font-display text-[1.1875rem] italic leading-relaxed text-ink\">“Nagsabi lang ako na magswitch sa back up power then bumalik din ako sa meeting. That shows reliability sa client.”</blockquote><p class=\"mt-5 text-[0.9375rem] leading-relaxed text-ink-2\">In an August 2026 r/buhaydigital thread asking VAs earning six figures a month how they stay stable, one reply stood out for being unglamorous. She said freelancing is a business, so she invested in the business first: a laptop with better specs so work finished faster, then backup internet, then backup power. During a meeting the power went out. She said she was switching to backup, switched, and rejoined. She also noted that co-workers who repeatedly had no power or no internet were eventually let go, and that understanding clients exist but should not be abused.</p><div class=\"mt-5 rounded-xl border border-teal-pale bg-teal-wash/60 p-4\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The lesson</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Reliability is a purchasable skill, and it is cheaper than most upskilling. A UPS and a loaded backup SIM cost less than one course and protect every peso you earn. Her rule is the whole lesson: you should show up when you are needed.</p></div><a href=\"https://old.reddit.com/r/buhaydigital/comments/1veawtz/tanong_ko_lang_sa_mga_va_dito_earning_6_digits/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"mt-4 inline-block text-[0.8125rem] font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">Read the original thread — r/buhaydigital, August 2026</a></figure></div><section id=\"first-client\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Getting the first one to say yes</h2><ol class=\"mt-7 space-y-4\"><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">01</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Fix the profile before you send anything</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">On OnlineJobs.ph, fill everything: photo, government ID, Facebook URL, address with a recent bill, and written skill descriptions. More honest detail means a higher ID Proof score, and a lot of employers filter out low scores before they read a word you wrote.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">02</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Apply to the adjacent titles, not just &quot;virtual assistant&quot;</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Admin coordinator, customer support representative, operations assistant, scheduling assistant, listing coordinator. The same work, a fraction of the applicants.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">03</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Consider an agency for the first role</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Agencies pay less per hour and place you faster because they already hold the client relationships. Six months of real experience is worth more than six months of applying cold. Take it, learn, then go direct.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">04</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Tell every human you know what you now do</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Referrals dominate this market. Not &quot;I am looking for work online&quot; but the exact sentence: I do X for Y so they can Z. People cannot refer a category.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">05</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Offer a small paid pilot instead of free work</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">&quot;Give me one paid week on the inbox and you will see Friday&#x27;s report&quot; converts better than a discount and it puts a price on you from the first day.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">06</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Keep applying after you sign</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">One client is not a job, it is a single point of failure. The common advice from VAs earning well is blunt: never let one client be more than half your income.</p></div></li></ol><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">What goes in the portfolio</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">Every one of these comes out of the exercises above. Finish the track and you have the folder, not just the knowledge.</p><ul class=\"mt-5 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Two-minute Loom introduction</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Proves your English, your energy, and your setup in one file. Most applicants send nothing like it.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">One SOP with screenshots and a failure branch</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">The single most senior-looking thing a beginner can produce.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Before and after of a customer reply</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Shows judgment and tone, which is what clients are actually screening for.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A tracker sheet with one clever formula</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Signals that you build small systems rather than doing everything by hand.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A one-page weekly report</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Answers the client&#x27;s real fear: will I know what is happening without asking.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Your setup and outage plan</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Directly de-risks hiring someone in a country they associate with typhoons and brownouts.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A rate and scope one-pager</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Lets a client picture the arrangement instead of starting a negotiation from zero.</p></li></ul></div></section>"},{"kind":"slot","value":"QUIZ","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":""},{"kind":"slot","value":"GLOSSARY","wrappers":[{"tag":"section","class":"border-y border-line bg-paper-2/70 py-14 sm:py-20"},{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"red-flags\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Walk away when you see these</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Not every one of these is a scam. Some are just clients who will cost you more than they pay you, which ends the same way.</p><ul class=\"mt-7 space-y-3\"><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>A check, gift cards, or equipment you must buy from their vendor</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">The fake-check scam, every time. Money never flows through a VA.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>You are asked to pay for training, a kit, or a placement fee</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Employers pay you. Anyone charging you to be hired is selling you the hiring, not the job.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Hired from a text chat with no video call at all</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Real clients want to hear you speak before handing over their inbox. Scammers avoid faces.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>No contract and no written scope</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Without it, every disagreement is decided by whoever is more stubborn, and they hold the money.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>&quot;We pay after your first month&quot; from a stranger</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">You would be lending a stranger a month of your labour. Weekly or biweekly in month one.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>The rate is far above market for basic admin</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Wildly generous offers are bait designed to stop you asking normal questions.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>They want your bank login, your ID before any contract, or a selfie holding your ID</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">That package is identity theft raw material. Documents come at contract stage, to a verifiable company.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>The scope keeps growing before you have even started</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">If it creeps during courtship, it will be unrecognisable by month two.</p></li></ul></section></div><section id=\"faq\" class=\"scroll-mt-32 border-t border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Questions people actually ask</h2><div class=\"mt-7 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Do I need a certificate or a paid VA course to get hired?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Clients almost never ask. They ask what you can do and whether you have shown it. A proof folder built in one weekend outperforms most certificates, and it costs nothing.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">How long does it realistically take to land the first client?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Four to twelve weeks if you have a lane, a proof folder, and you send tailored applications daily. Indefinitely if you apply as &quot;a VA&quot; with a resume. The variable that matters is specificity, not luck.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Should I start with an agency or go direct?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Direct pays more. Agencies place you faster because they already have the clients. If you have been applying cold for two months with nothing, take the agency role, get six months of real workflow experience, and leave with a portfolio.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">What laptop do I need?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">For admin work, 8GB of RAM and an SSD is a comfortable floor. Spend your first upgrade money on connection reliability and a decent headset before you spend it on a faster machine.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Do I have to register with the BIR?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Freelancers are self-employed and are expected to register and file. Many elect the 8 percent option where eligible instead of graduated rates plus percentage tax. Pay an accountant for one consultation early. It is cheap compared to sorting out three years of nothing.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Is it bad to take a $3 an hour job just to start?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">It is a defensible entry point and a terrible destination. Take it with a stated end date, extract the experience and the samples, and raise or leave within six months. The people who never escape are the ones who never set the date.</p></details></div><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">Where the facts in this course came from</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">All free, all worth your time. Open them in another tab and check us.</p><ul class=\"mt-5 space-y-2.5\"><li><a href=\"https://blog.onlinejobs.ph/comprehensive-guide-to-virtual-assistant-salaries-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">OnlineJobs.ph salary guide</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">The most useful Philippine rate benchmark. Updated April 2026.</span></a></li><li><a href=\"https://blog.onlinejobs.ph/everything-you-need-to-know-about-idproof\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Everything you need to know about ID Proof</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Exactly what raises your ID Proof score, including the address and billing document rules.</span></a></li><li><a href=\"https://www.reddit.com/r/buhaydigital/comments/1f4ifrx/start_here_frequently_asked_questions_in/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">r/buhaydigital, Start Here FAQ</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">The pinned Filipino remote work FAQ. Scams, payment platforms, laptop specs, where to find work.</span></a></li><li><a href=\"https://wise.com/ph/blog/payoneer-vs-paypal\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Payoneer vs PayPal in the Philippines</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Fee comparison written by a competitor, so read it critically, but the mechanics are accurate.</span></a></li><li><a href=\"https://www.respicio.ph/commentaries/bir-registration-for-freelancers-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">BIR registration for freelancers</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Plain explanation of registration and the tax options available to self-employed Filipinos.</span></a></li><li><a href=\"https://toggl.com/track/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Toggl Track</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free tier</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Your own independent time log. The thing that settles billing disputes in your favour.</span></a></li></ul></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-16\"><div class=\"rounded-2xl border border-line bg-clay-wash/60 p-7 sm:p-9\"><h2 class=\"font-display text-[1.5rem] font-semibold text-ink\">Finished? Go and use it.</h2><p class=\"mt-3 max-w-lg text-[0.9375rem] leading-relaxed text-ink-2\">The board updates every 30 minutes. Filter for this specialism, check your number against the rate tool, and send five tailored applications rather than fifty copy-pasted ones.</p><div class=\"mt-6 flex flex-wrap gap-3\"><a class=\"btn btn-primary\" href=\"/jobs\">See jobs on the board</a><a class=\"btn btn-ghost\" href=\"/pricing-tool\">Check your rate</a></div></div><div class=\"mt-10\"><p class=\"eyebrow text-muted\">Other written tracks</p><ul class=\"mt-3 flex flex-wrap gap-2.5\"><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/executive-assistant\">Executive Assistant</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/seo-specialist\">SEO Specialist VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/social-media-manager\">Social Media Manager VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/real-estate-va\">Real Estate VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/ecommerce-va\">E-commerce VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/applications-that-get-replies\">Applications That Get Replies</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/pricing-and-negotiation\">Pricing &amp; Negotiation</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/becoming-an-ops-lead\">Becoming an Operations Lead</a></li></ul></div><a class=\"btn btn-ghost mt-8\" href=\"/courses\">← All courses</a></div><!--$--><!--/$-->"}],"modules":[{"n":1,"title":"What the job actually is","outcome":"You can describe VA work in terms of outcomes a business pays for, and you know which myths to drop before they cost you money.","badges":["Time split","Rates","Red/green flags"],"minutes":20,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A client is not buying your hours. They are buying the removal of a specific problem, and hours are just the unit they happen to pay in.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">&quot;Virtual assistant&quot; is a category the way &quot;food&quot; is a category. Nobody orders food. They order adobo.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The three things clients complain about most are missed deadlines, silence, and having to check your work. Notice that none of them are about talent.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You are running a business with one employee. That means you handle your own taxes, your own downtime, your own equipment, and your own sick days.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">There is no certificate that unlocks this. Proof of work unlocks it, and you can manufacture proof of work in a weekend.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The same person, described two ways</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&quot;Hardworking and passionate virtual assistant. Fast learner, detail-oriented, willing to be trained. I can do admin tasks, data entry, social media, email management, and more.&quot;</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&quot;I keep small service businesses out of inbox chaos. For a two-person home-organising company I sort the inbox by 9am, reply to booking enquiries within an hour using approved templates, and send a Friday summary of every job booked and every quote still open.&quot;</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The second one is not more experienced. It is more specific. Specificity is free and it is the entire difference in reply rate.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Where the hours go</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">What general VA work is actually made of</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A typical full-time general VA role, before you specialise. This is the mix you&#x27;re trying to escape from.</p><div class=\"mt-4\"><div class=\"flex flex-col items-center gap-5 sm:flex-row sm:items-start sm:gap-7\"><svg viewBox=\"0 0 140 140\" class=\"h-[8.5rem] w-[8.5rem] shrink-0 -rotate-90\" role=\"img\" aria-labelledby=\"_R_b1lanpfiuqbtb_\"><title id=\"_R_b1lanpfiuqbtb_\">Admin: email, calendar, data entry 34%, Customer or client communication 22%, Research and reporting 16%, Content, social, marketing support 12%, Process and documentation 9%, Ad hoc &quot;can you just...&quot; 7%</title><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"var(--color-line)\" stroke-width=\"20\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#097769\" stroke-width=\"20\" stroke-dasharray=\"119.63184824869933 232.2265289533575\" stroke-dashoffset=\"0\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#5fd0bf\" stroke-width=\"20\" stroke-dasharray=\"77.4088429844525 274.4495342176043\" stroke-dashoffset=\"-119.63184824869933\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#075f55\" stroke-width=\"20\" stroke-dasharray=\"56.297340352329094 295.5610368497277\" stroke-dashoffset=\"-197.04069123315185\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#e07a2f\" stroke-width=\"20\" stroke-dasharray=\"42.223005264246815 309.63537193781\" stroke-dashoffset=\"-253.33803158548093\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#4453b8\" stroke-width=\"20\" stroke-dasharray=\"31.667253948185113 320.1911232538717\" stroke-dashoffset=\"-295.56103684972777\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#c3e6df\" stroke-width=\"20\" stroke-dasharray=\"24.63008640414398 327.22829079791285\" stroke-dashoffset=\"-327.2282907979129\"></circle></svg><ul class=\"w-full space-y-2\"><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#097769\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Admin: email, calendar, data entry</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">34%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">The baseline. Necessary, replaceable, cheap.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#5fd0bf\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Customer or client communication</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">22%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Where trust gets built. Get good here and everything else opens up.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#075f55\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Research and reporting</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">16%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Often badly briefed. Learning to scope this well is an early differentiator.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#e07a2f\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Content, social, marketing support</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">12%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">The gateway drug to a specialism. Volunteer for it.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#4453b8\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Process and documentation</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">9%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Nobody asks for it. Doing it anyway is how you get promoted.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#c3e6df\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Ad hoc &quot;can you just...&quot;</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">7%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Uncapped, this eats everything. Track it or it becomes your whole job.</p></li></ul></div><p class=\"mt-4 border-t border-line pt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">A third of the job is work anyone can do, priced accordingly. The route up is to grow the specialist slices and let the admin slice shrink — deliberately, not by accident.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">The whole VA pay ladder, honestly</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">This is the map for everything that follows. Most people who quit VA work quit because they stayed on row one for three years without realising rows three and four existed.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:38rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Entry (0–1 yr)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$3–5</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$480–900</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">General admin, data entry, research. You do what you&#x27;re told. Everyone starts here.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Junior (1–2 yrs)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$5–7</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$800–1,150</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You work unsupervised in one area and your work needs little checking.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Mid / specialist (2–4 yrs)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$7–11</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,150–1,800</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You have a lane — SEO, ecommerce, EA, bookkeeping. This is where the market widens.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Senior (4–6 yrs)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$11–16</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,800–2,600</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You own outcomes, not tasks. You can say no to a client and be right.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Lead / ops (6+ yrs)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$16–25+</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$2,600–4,000+</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You run systems and other people. Judgment is what you&#x27;re paid for.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><div class=\"mt-4\"><p class=\"eyebrow mb-2 text-muted\">Same skill, different client</p><ul class=\"grid gap-2 sm:grid-cols-2\"><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Verse&#x27;s job board (general VA median)</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$3.50</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">The real median across live listings. Half of all posts are below this. Don&#x27;t let it anchor you.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Same board, top 10% of posts</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$6.20+</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">The good jobs exist on the same board. They&#x27;re just outnumbered.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Specialist (SEO, PPC, bookkeeping)</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$8–17</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Picking a lane is worth roughly double. This is the single highest-return decision you&#x27;ll make.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">US client, direct (any specialism)</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$7–18</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Direct beats agency and beats marketplace, once you can hold a client relationship yourself.</p></li></ul></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Sources: 2,081 live listings on Verse&#x27;s own board, OnlineJobs.ph salary data, and 2026 agency rate cards. Where sources disagree, the lower number is usually what&#x27;s actually posted and the higher is what good people actually get.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">How you describe what you do</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;I&#x27;m a virtual assistant. I can do anything you need — admin, social media, customer service, data entry, research, whatever. I&#x27;m a fast learner and very hardworking.&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">&quot;Anything you need&quot; tells a client nothing and puts you in the cheapest possible bucket. Fast learner and hardworking are what every single applicant says, so they carry zero information.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;I run inbox and calendar for founders. Last month I took a client&#x27;s inbox from 200+ unread daily to under 10, and rebuilt their week so they got two mornings of uninterrupted time back. I work 6am–2pm PST.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">A named lane, a specific result with a number, and the practical detail they actually need. Narrow gets hired; general gets ignored.</p></div></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Find five real job posts on OnlineJobs.ph or Indeed PH that you could half-do today. Copy the responsibilities into a sheet.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A sheet with five posts, and for each one: the outcome the client actually wants, in your own words, in one sentence.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 45 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Your one-sentence outcome never uses the word &quot;assist&quot;</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You noted the tools each post names</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You marked which of the five you could do worst, honestly</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You noted the rate or salary if it was posted</span></label></li></ul></div>"},{"n":2,"title":"The setup floor","outcome":"Your internet, power, and audio meet the bar clients quietly test in the first week, and you know what to say when they fail anyway.","badges":["Rates","Red/green flags","1 template"],"minutes":26,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The practical bar for admin work is roughly 25 to 50 Mbps down and 10 to 20 Mbps up. If you are on video calls most of the day, aim closer to 100 down and 25 up.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Upload speed is what makes you look bad on calls, and it is the number nobody checks. Test it, screenshot it, keep the screenshot.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Brownouts are not an excuse, they are a planning problem. A UPS on the router plus a charged laptop plus mobile data buys you three hours of looking completely fine.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Have a written outage plan and give it to the client in week one: what you switch to, how fast, and how you will tell them.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Audio beats video. A cheap wired headset makes you sound competent. A good camera with laptop-mic audio does not.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">One Filipino VA earning six figures a month described switching to backup power mid-meeting and rejoining, and said her co-workers who kept disappearing for power and internet were eventually let go. Her rule: &quot;you should show up when you are needed.&quot;</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The outage plan you paste into your onboarding doc</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Primary: Converge fibre, 100/50 Mbps. Speed test screenshot attached, run 4 Aug.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Backup 1: Globe mobile data hotspot, unlimited daily load, tested weekly.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Backup 2: coworking space 15 minutes away, open 8am to 10pm.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Power: router and modem on a UPS, roughly 90 minutes. Laptop holds 5 hours.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">If I go down: I message the Slack channel within 5 minutes from my phone, with an ETA and what I am switching to.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">If I cannot recover within 30 minutes: I hand off anything time-critical with a Loom and a written status.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Nobody else sends this. It costs you 20 minutes and it makes you look like the least risky hire in the pile.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">What the setup floor actually costs</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Real prices in the Philippines. You do not need most of the expensive things to start, but the first three rows are genuinely non-negotiable.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:38rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Non-negotiable</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">One-off</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">₱0–2,000</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Working laptop, headset with a mic, Google account, a quiet corner. Most of this you already have.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Internet — the real requirement</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">₱1,500–2,500/mo</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">25 Mbps+ fibre</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Plus a mobile data backup plan. Dropping off a client call is the fastest way to lose a client.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Power backup</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">₱2,500–6,000 one-off</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">UPS or a big power bank</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Brownouts are a fact of life here. A UPS that buys you 20 minutes to say &quot;I&#x27;m switching to mobile data&quot; is worth every peso.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Nice to have, month 2+</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">₱500–1,200/mo</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">Canva Pro, a password manager, a second screen</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Let your first client&#x27;s money buy these. Don&#x27;t fund them before you have income.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Don&#x27;t buy yet</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">₱0</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">Courses, certifications, expensive tools</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Nobody has ever been hired for a VA certificate. Portfolio and proof beat paper every time.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Total realistic start-up cost if you already own a laptop: under ₱5,000. Anyone telling you that you must buy their ₱15,000 course first is selling you the course, not the career.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Your internet drops mid-shift</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Going silent for 40 minutes while you restart the router, then messaging &quot;sorry, my internet was down&quot; once it&#x27;s back.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">From the client&#x27;s side you simply disappeared during working hours. The outage is forgivable; the silence is what makes them wonder whether you were working at all.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Switching to mobile hotspot within two minutes and posting: &quot;Fibre&#x27;s down at my end — I&#x27;m on mobile data now, fully working. Video might be rough for the 2pm call, happy to do audio only. I&#x27;ll flag if anything changes.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">You had a backup, you used it fast, you told them before they noticed, and you pre-solved the one thing it affects. Nobody expects perfect infrastructure. They expect you to handle it.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Workspace and reliability checklist</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Work through this before you apply to anything. Half of first-month firings are reliability problems, not skill problems.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>THE FLOOR — you genuinely cannot work without these\n[ ] Laptop/desktop that boots in under a minute and runs 8 hrs without dying\n[ ] Wired or stable fibre, 25 Mbps+ — test at speedtest.net during YOUR working hours, not at noon\n[ ] Backup internet: mobile data with a plan you&#x27;ve actually tested\n[ ] Headset with a real mic. Not earbuds, not laptop mic. ₱800 changes how professional you sound.\n[ ] Quiet space for calls. Roosters, tricycles and karaoke are all audible on Zoom.\n[ ] Google account with your real name — not xXdarkangelXx@\n[ ] Power backup: UPS, or a laptop that holds charge + phone hotspot\n\nTEST IT PROPERLY (do this before you promise anyone anything)\n[ ] Speedtest at 3am, 9am and 8pm — the numbers will differ\n[ ] Record yourself on Zoom for 2 min. Watch it back. How&#x27;s the audio? The lighting? The background?\n[ ] Unplug the router mid-call and time how long your switch to mobile data takes. Under 2 min?\n[ ] Run 8 hours on battery + hotspot as a drill. Does it survive?\n\nPROFESSIONAL BASICS\n[ ] Email signature: name, role, timezone\n[ ] Profile photo: clear face, plain background, good light. A phone photo against a white wall is fine.\n[ ] Calendly or similar, with your real availability\n[ ] A password manager (Bitwarden is free) — you&#x27;ll be handling client logins\n[ ] A folder structure for client work that isn&#x27;t Downloads\n\nTHE BROWNOUT PLAN — write this down before you need it\n1. Switch to hotspot immediately\n2. Message the client within 5 minutes, before they notice\n3. If power&#x27;s out over 2 hrs: name the nearest backup location (a café, a relative&#x27;s, a co-working space)\n4. Have that location&#x27;s address and hours written down NOW, not during the outage</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Run a speed test at the worst hour of your day, not the best. Then write your outage plan using the six lines above.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page outage plan with a real speed test screenshot embedded.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 40 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The speed test was run during your intended working hours</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Both backups are real and you have actually tested one this week</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You committed to a specific notification time, in minutes</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There is a handoff step for when recovery fails</span></label></li></ul></div>"},{"n":3,"title":"Your working stack","outcome":"You can move around Google Workspace, Slack and a task board without asking, and you know the access rules that protect you.","badges":["Workflow","Tools"],"minutes":28,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Learn the four verbs in every tool: create, share, assign, and find again later. That is genuinely most of it.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">In Drive, folder structure beats search. Client name, then year, then function. Files named client-document-YYYY-MM-DD.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">In Slack, reply in threads, not the channel. Use the client&#x27;s channel for work and DMs for nothing that should be findable later.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">On the task board, a task without an owner and a due date is a wish. Add both or do not add the task.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never take an owner login. Ask for a delegated account, a staff role, or an invite to their password manager. If something goes missing on a shared login there is no record proving it was not you.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Do the client&#x27;s work in the client&#x27;s accounts. Your personal Drive is not a place to store their customer list.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Two ways to ask for access</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&quot;Hi Dee, can you send me your Gmail password so I can start on the inbox?&quot;</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&quot;Hi Dee, for the inbox I need delegate access rather than your password. In Gmail: Settings, Accounts and Import, Grant access to your account, add my email. It lets me read and reply as you without ever holding your login, and you can revoke it in one click. Takes about 40 seconds, happy to send a Loom.&quot;</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">You just taught the client something and reduced their risk in one message. That is what senior looks like on day one.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Learning a tool fast enough to say you know it</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A job post names a tool you&#x27;ve never used. You have a weekend.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Find the free tier and sign up today</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Almost every tool on earth has one. You cannot learn software by reading about it.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Build one real thing, not a tutorial</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Set up a fake client project. Real stakes-free practice beats following along with a video, because you&#x27;ll hit the confusing bits.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Watch one 20-minute overview, then stop</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Enough to know the vocabulary. Tutorial-watching feels productive and teaches almost nothing beyond the first video.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Learn the four things every tool has</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">How to create, how to organise, how to share/permission, how to report. Every tool in this category is a variation on those four.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Screenshot what you built</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">This is now a portfolio piece. &quot;I set up a project board for a mock client&quot; is infinitely better than &quot;familiar with Asana&quot;.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Be honest about your level in the interview</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">&quot;I&#x27;ve built with it, I&#x27;m not an expert, and I picked it up over a weekend&quot; is a strong answer. Getting caught overclaiming is fatal.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Collecting tools instead of skills. Ten tools at 20% is worth less than three at 90%, and clients can tell the difference within a week.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Tool comparison</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">The tools worth learning first</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Learn these in this order. Every one is free or has a real free tier. You do not need to know all of them before applying — you need to be genuinely fast in the top three.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:52rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Tool</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Best for</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Learning curve</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Cost</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Verdict</th></tr></thead><tbody><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Google Workspace</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Docs, Sheets, Gmail, Calendar, Drive. The substrate of almost every VA job.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy to open, deep to master</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Sheets specifically. Learn VLOOKUP, filters, pivot tables and conditional formatting. This alone moves you up a pay band.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Slack</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Where remote teams actually talk.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — an afternoon</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Learn threads, DND, saved items and how to not @channel. Bad Slack etiquette reads as inexperience immediately.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Notion / ClickUp / Asana / Trello</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Task and project tracking. Pick ONE.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — a weekend</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">They all do the same four things. Learn one properly and you can pick up any other in a day. Say that in interviews.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Loom</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Async explanation. Screen + voice.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Instant</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier (5 min limit)</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Wildly underused by VAs. A 90-second Loom in an application puts you ahead of 95% of candidates. Use it.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Canva</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Any visual, ever. Templates, brand kits, quick graphics.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — a weekend</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Even if design isn&#x27;t your lane, basic Canva makes you useful in a hundred small moments.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Bitwarden / 1Password</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Handling client credentials safely.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — an hour</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free (Bitwarden)</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Saying &quot;send it to my Bitwarden, never Slack&quot; in an interview is a genuine trust signal. Costs nothing, learns in an hour.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">ChatGPT / Claude</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Drafting, summarising, checking your English, restructuring messy notes.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy to use, hard to use well</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Use it to draft and check, never to send unread. Clients can tell. Being caught sending raw AI output loses the job.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 5 columns and scrolls horizontally on small screens.</span></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build the full folder and board setup for Sortly Home as if you started Monday: Drive structure, a Trello or Notion board with four columns, and an access request message.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: Screenshots of the Drive tree and the board, plus the access message written out.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 60 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Folder names would still make sense to a stranger in a year</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every sample task on the board has an owner and a date</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The access message names the exact menu path, not just the idea</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Nothing anywhere asks for a raw password</span></label></li></ul></div>"},{"n":4,"title":"Pick a lane","outcome":"You have one narrow offer with a named buyer, and you stop competing with fifty thousand generalists.","badges":["Workflow","Rates","Red/green flags"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Niche is not a personality. It is the intersection of a business type and a repeated problem: &quot;inbox and booking for small home-service businesses&quot; is a niche, &quot;admin&quot; is not.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Pick by adjacency, not by passion. What did your last job, your degree, or your side hustle expose you to? A former nurse pitching medical VA work starts three years ahead of a stranger.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Narrow feels dangerous because it seems to remove options. It removes competition, which is the thing that is actually stopping you.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You can change lanes later, and you will. Nobody is checking.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Test your lane in one sentence: &quot;I do X for Y so they can Z.&quot; If you cannot fill in Y with a real business type, you do not have a lane yet.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">One VA who hires described the fix bluntly: post the work itself, not claims. &quot;Most clients scan portfolios in 30 seconds and they want to see the work, not read about it.&quot;</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Three lanes built from ordinary backgrounds</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Ex-call-centre agent: &quot;I run first-response customer support for Shopify stores in the US morning, so refunds and where-is-my-order get answered before the owner wakes up.&quot;</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Ex-teacher: &quot;I do course admin for online educators. Student onboarding, Q and A moderation, and the weekly progress email.&quot;</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Ex-bank teller: &quot;I do receipt and expense cleanup for US small businesses in QuickBooks, so month-end takes their accountant two hours instead of two days.&quot;</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">None of these people had VA experience. All three named a buyer and a repeated problem.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Your background is not a handicap to explain away. It is the only thing that makes your version of the offer different.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Choosing a lane in one week</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">You&#x27;ve read the rate table and you&#x27;re paralysed by options.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Cross off anything you&#x27;d genuinely hate</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Two years is a long time. If cold calling makes you physically anxious, ISA work isn&#x27;t a brave choice, it&#x27;s a resignation letter with a delay.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Search Verse&#x27;s board for each remaining lane and count the posts</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Demand is not evenly spread. A lane you love with four listings a month is a hobby.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Check what the top of each lane requires</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">SEO&#x27;s ceiling needs analytics comfort. Ecommerce&#x27;s needs spreadsheet fluency. EA&#x27;s needs discretion and nerve. Be honest about which you have.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Spend one evening doing the actual work</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Write a keyword map. Build a Shopify dev store. Fix a fake calendar. An evening of the real thing beats a month of deliberating.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Commit for six months, in writing, to yourself</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Lane-hopping every two months is the same as having no lane. Six months is long enough to know.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Rewrite your profile so it says one thing</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Your headline, your pitch and your portfolio all say the same lane. This feels risky and narrow. That&#x27;s why it works.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Picking the highest-paying lane on the table with no interest in it. You&#x27;ll be competing against people who find it genuinely interesting, and they&#x27;ll out-learn you inside a year.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">What each lane pays, so you can choose with open eyes</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">This is the single most valuable table in the course. Pick based on what you can stand doing for two years, but pick with the numbers in front of you.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:38rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">General admin / data entry</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$3–6</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$500–1,000</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Easiest to get, hardest to grow from, most exposed to AI. A starting point, not a destination.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Customer support</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$5–9</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$850–1,450</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Steady demand, unsociable hours. Good stepping stone into ecommerce ops.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Executive assistant</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$7–14</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,150–2,300</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">High trust, high retention. Best lane if you&#x27;re organised and discreet.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Social media / content</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$5–14</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$850–2,200</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Huge range depending on whether you make assets or just schedule them. Video editing is the premium bit.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Ecommerce ops</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$5–17</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$850–2,700</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Amazon PPC is the top of this range and one of the best-paid VA niches going.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">SEO / content marketing</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$6–18</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,000–2,900</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Measurable results mean a genuinely high ceiling. Slow to learn, worth it.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Bookkeeping</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$6–14</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,000–2,300</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Xero/QuickBooks certification actually matters here — one of the few places a cert pays.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Ops / project management</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$10–25</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,700–4,000</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The top of the VA ladder. You get here from any other lane, not directly.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Sources: Verse&#x27;s live board, OnlineJobs.ph tiers, 2026 agency cards. Ranges overlap because the low end is &#x27;does the task&#x27; and the high end is &#x27;owns the outcome&#x27; — in every single lane.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Choosing your lane</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;I&#x27;ll do general VA work for now and specialise later once I have more experience and know what I like.&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">This is the most common and most expensive mistake in this career. General work doesn&#x27;t naturally lead anywhere — it leads to more general work at the same rate. Two years in, you have two years of experience being interchangeable.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;I&#x27;m taking general VA work to pay the bills, and I&#x27;ve picked ecommerce as my lane. I&#x27;m spending 4 hours a week on a Shopify dev store, and I&#x27;ll only apply to ecommerce-adjacent roles from month three. By month six every application says ecommerce.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Accepts the reality of needing income now, but sets a direction, a weekly investment and a deadline. Specialising isn&#x27;t something that happens to you.</p></div></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write three candidate lanes using the &quot;I do X for Y so they can Z&quot; sentence. Then search each one on a job board and count the posts from the last 30 days.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page decision note: three lanes, post counts, and the one you are picking with your reason.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 50 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every lane names a business type, not a job title</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You actually counted posts rather than guessing</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You rejected at least one lane for a stated reason</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The chosen lane connects to something you have already done</span></label></li></ul></div>"},{"n":5,"title":"Talking to clients so they relax","outcome":"You can write status updates, ask questions that do not create work, and escalate without panic.","badges":["Red/green flags","1 template"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The four lines that keep beginners employed: what I finished, what I am blocked on, what I am doing next, and anything you need to decide.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Send it every day for the first two weeks, then at whatever cadence the client prefers. Never go a full working day silent.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Batch your questions. Three numbered questions in one message is a professional. Three separate pings in an hour is a cost.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Ask questions with a proposed answer attached: &quot;I plan to do A because B. Shout if you want otherwise.&quot; The client gets to say yes instead of doing your thinking.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">When you make a mistake, report it before it is discovered, with what happened, what you already did, and what you changed. Almost nobody is fired for the mistake.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Confirm the definition of done before you start anything that takes more than an hour. &quot;Done&quot; means different things to you and to them roughly always.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The end-of-day update, weak and strong</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&quot;Hi Dee! Done for today. I worked on the inbox and the spreadsheet. Let me know if you need anything else. Thank you!&quot;</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Done: inbox at zero, 11 booking enquiries answered from the template, 3 needed your pricing so they are in the Waiting-on-Dee list.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Blocked: the Baxter quote. The old file has two different prices and I do not know which is current.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Next: tomorrow I clean the client spreadsheet, target is a single sheet with no duplicate rows by noon.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">You decide: do we still offer the 10 percent repeat-client discount? Two people asked today.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The second version takes four minutes and answers every question your client was about to ask at 11pm.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">You made a mistake — sent the wrong file to a client&#x27;s customer</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Saying nothing and hoping nobody noticed. Or a long message full of apology: &quot;I&#x27;m so so sorry, I feel terrible, I completely understand if you want to end our contract, I don&#x27;t know how I could be so careless...&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Hiding is worse than the mistake, always. And the apology spiral makes it about your feelings — now the client has to manage YOUR distress on top of fixing the problem.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;I sent the wrong attachment to Dave at 2:14pm — the internal pricing sheet instead of the proposal. I&#x27;ve emailed him asking him to delete it and sent the correct file. Here&#x27;s what he saw: [screenshot]. To stop it happening again I&#x27;m attaching files before writing the recipient line from now on. Anything else you want me to do?&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Fast, factual, no drama, includes what they saw, and names a concrete process change. Clients keep VAs who own mistakes cleanly. They fire the ones who hide them.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">You don&#x27;t understand the task you&#x27;ve been given</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Saying &quot;okay, got it!&quot; and then spending four hours producing something wrong, or messaging six separate questions over the course of a day.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">The first wastes a day and destroys trust. The second interrupts them six times, which is the specific thing they hired you to prevent.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Before I start — I want to check I&#x27;ve got this right. You want [restatement in my own words], done by [date], and the output is [format]. Two things I&#x27;m unsure about: (1) should this include [X]? (2) is [Y] in scope or separate? If I don&#x27;t hear back by 3pm I&#x27;ll assume yes to both and flag anything odd.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">One message, restated in your own words so they can catch a misunderstanding, specific questions batched together, and a default so you&#x27;re never blocked.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The five messages you&#x27;ll send constantly</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Almost all client communication is one of these five shapes. Learn them and you stop agonising over wording.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>1. ACKNOWLEDGING A TASK\n&quot;Got it — [restated in my own words]. I&#x27;ll have it to you by [specific time]. Will flag if anything blocks me.&quot;\n(Never just &quot;ok&quot; or a thumbs up on something substantial. Restating proves you understood.)\n\n2. ASKING A QUESTION WITHOUT LOOKING LOST\n&quot;Quick one on [task]: I&#x27;m going with [my assumption] unless you say otherwise. Only thing I can&#x27;t work out is [specific question]. Carrying on in the meantime.&quot;\n(Always come with a proposed answer. A question with a default is 10 seconds of their time; a question without one is a meeting.)\n\n3. FLAGGING A DELAY — the moment you know, never on the deadline\n&quot;[Task] is going to slip to [new date]. Reason: [honest, brief, no excuses]. What I&#x27;ve done so far: [progress]. If you need it by the original date I can [the reduced version] instead — your call.&quot;\n(Early + an option = a minor thing. Late + an excuse = a trust problem.)\n\n4. OWNING A MISTAKE\n&quot;I made an error on [thing] at [time]. What happened: [facts]. Impact: [what it affected]. What I&#x27;ve done: [fix]. To stop it recurring: [process change].&quot;\n(No spiral, no over-apologising. One &quot;sorry&quot; maximum, at the start.)\n\n5. THE END-OF-DAY UPDATE\n&quot;EOD [date]\nDone: [things]\nIn progress: [thing] — [where it&#x27;s at]\nNeeds you: [thing] — by [date]\nTomorrow: [what I&#x27;m starting with]&quot;\n(Send this daily for your first month even if nobody asked. It&#x27;s the single fastest way to build trust with a new client.)\n\nUNIVERSAL RULES\n• Reply within your agreed window, even if the reply is &quot;seen this, looking at it now&quot;\n• Never go silent. Silence is the only unforgivable thing.\n• Say &quot;I don&#x27;t know, I&#x27;ll find out by [time]&quot; instead of guessing\n• If it&#x27;s over 4 sentences, put the ask in the FIRST line, not the last</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write three end-of-day updates for an imagined first week at Sortly Home: a good day, a day where you were blocked all afternoon, and a day where you broke something.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: Three updates, each under 100 words, using the four-line structure.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 40 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The blocked day states exactly what you tried before asking</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The mistake update leads with the mistake, not with an apology paragraph</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every update ends with a decision or a clear next action</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">No sentence begins with &quot;Just wanted to&quot;</span></label></li></ul></div>"},{"n":6,"title":"Document as you go","outcome":"You can turn any repeated task into an SOP a stranger could follow, which is the artefact that gets you promoted.","badges":["Workflow","1 template"],"minutes":28,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Write the SOP the second time you do a task, not the tenth. The second time is when you still remember what confused you.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A usable SOP has five parts: what it is for, when it runs, what you need before starting, numbered steps with screenshots, and how you know it worked.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Steps start with a verb and describe one action. If a step has an &quot;and&quot; in it, it is two steps.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Add the failure branch. &quot;If the payment does not appear in Stripe within 10 minutes, do this.&quot; That branch is where the value is.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Record a Loom next to the doc. Some people read, some people watch, and clients love that you offered both.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">SOPs make you replaceable in the small sense and irreplaceable in the large sense. The person who documents the system gets asked to run the system.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — SOP: answering a Sortly Home booking enquiry</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Purpose: reply to every new booking enquiry within one business hour with a price and a next step.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Runs: every weekday, 8am and 1pm Portland time.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">You need: the Gmail delegate access, the pricing sheet, the Calendly link.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">1. Open the label Enquiries in Gmail.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">2. Read the message and find the square footage and the suburb.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">3. Match the square footage to a band in the pricing sheet, tab Residential.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">4. If the suburb is outside the service map, use template Out of Area and stop here.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">5. Reply using template Standard Quote, filling the price, the two nearest available slots, and the Calendly link.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">6. Apply the label Quoted and add a row to the Quotes tracker with the date and amount.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Done when: the thread is labelled Quoted and the tracker row exists. Failure branch: if the sheet has two prices for one band, do not guess, ask Dee and log it in Blocked.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Six steps, one failure branch, one definition of done. Any competent stranger could run this tomorrow.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Document as you go, without it becoming a second job</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The second time you do any task. Never the first, always the second.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Screenshot while you work the second time</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Not a separate documentation session later. Screenshot as you go and the SOP is 80% written by the time you finish the task.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Write it for someone competent who has never seen this system</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Not for a beginner, not for yourself. That&#x27;s the right level of detail and it stops SOPs becoming novels.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Number the steps and put the decision points in bold</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">&quot;If the invoice is over $500, send to Maria first.&quot; The decision points are the actual value — anyone can click buttons.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Record a 2-minute Loom instead, if it&#x27;s fiddly</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Some things are far faster to show than write. A Loom plus five bullet points beats a 1,500-word document nobody reads.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Store it where the client will find it without you</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Their Drive, their Notion. Not your personal folder. An SOP only you can find is a hostage, not an asset.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Update it the moment it&#x27;s wrong</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A slightly outdated SOP is more dangerous than none, because people trust it. Fix it the day it breaks.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Thinking documentation makes you replaceable. The opposite is true — VAs who document get promoted to running things, because you can&#x27;t be given more responsibility if you&#x27;re the single point of failure on your current job.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">SOP template</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">One page per process. If it&#x27;s running past two pages, it&#x27;s two processes.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>SOP: [process name]\nOwner: [you] | Last updated: [date] | Runs: [daily/weekly/when X happens]\n\nWHY THIS EXISTS\n[One sentence. &quot;So that no invoice goes unpaid past 30 days.&quot; Context stops people improvising badly.]\n\nWHEN TO RUN IT\n[Trigger. A time, or an event. &quot;Every Monday 9am&quot; or &quot;whenever a new client signs&quot;.]\n\nWHAT YOU NEED FIRST\n• Access to: [tool] ([where the login lives — vault name, never the password])\n• [Any file, template or info needed]\n• Roughly [n] minutes\n\nTHE STEPS\n1. [Action.] [Screenshot]\n2. [Action.]\n3. **DECISION: if [condition], do [A]. Otherwise do [B].**\n4. [Action.]\n5. [Action.]\n\nHOW YOU KNOW IT WORKED\n[The check. &quot;The dashboard shows the new count&quot; / &quot;You receive the confirmation email&quot;.]\n\nWHEN IT GOES WRONG\n[Problem] → [what to do]\n[Problem] → [what to do]\nStill stuck → contact [person], and here&#x27;s what to tell them: [the info they&#x27;ll ask for]\n\nDON&#x27;T\n• [The thing that seems sensible but breaks something]\n• [The irreversible step]\n\nCHANGE LOG\n[date] — [what changed and why] — [who]</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Pick a task you personally do every week in real life. Paying a bill, doing groceries, a work process from an old job. Write it as a real SOP with screenshots.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one to two page SOP plus a Loom under three minutes walking through it.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 60 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every step starts with a verb and contains one action</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There is at least one failure branch</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The done condition is observable, not a feeling</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Someone else read it and did not need to ask you a question</span></label></li></ul></div>"},{"n":7,"title":"Hours, trackers, and honest time","outcome":"You can work under a tracker without resenting it, and you know your real effective hourly rate.","badges":["Red/green flags","1 template"],"minutes":24,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Many clients use Hubstaff or Time Doctor. They record time, activity levels, and often screenshots. It feels invasive because it is, and it is also completely normal in this market.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Read the policy before you accept: screenshot frequency, whether idle time is deducted, whether offline or manual time is allowed and who approves it.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Run your own timer in Toggl alongside the client&#x27;s tracker. When there is a billing dispute, your independent log is the thing that ends it.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Track by task, not by day. &quot;Inbox, 41 minutes&quot; is evidence. &quot;Tuesday, 8 hours&quot; is a story.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Calculate your effective rate monthly: money received divided by every hour you spent, including unpaid admin, calls, and job hunting. It is always lower than your quoted rate and it is the only number that matters.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">If a client refuses any tracking and also disputes your hours, that is not a tooling problem, that is a payment problem. Move to output-based pricing or move on.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Effective rate, first month at Sortly Home</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Quoted rate: $6 per hour. Billed: 60 hours. Received: $360, minus $9 in transfer and FX costs, so $351.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Unbilled time: 6 hours of onboarding calls, 3 hours learning their CRM, 4 hours writing SOPs, 5 hours applying to other jobs.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Total hours actually spent on this work: 78.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Effective rate: $351 divided by 78 equals $4.50 per hour.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Fix next month: onboarding is one paid hour not six, SOP writing is billable, and learning a client tool is billable at half rate by agreement.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">You did not have a rate problem, you had an unbilled-hours problem. Most beginners never find this because they never do the division.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A client asks you to install a screen-monitoring time tracker</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Refusing outright and treating it as an insult. Or accepting silently and then resenting every screenshot.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Screenshot trackers are normal in this market, especially on Upwork and with agencies. Refusing without discussion reads as having something to hide; accepting silently while resentful poisons the relationship slowly.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Happy to use [tracker] — most of my clients do. Two things to agree so it works for both of us: I&#x27;ll only run it during agreed hours, and I&#x27;ll pause it for breaks. If you see a low-activity stretch it&#x27;s usually a call or reading a long document — ask me and I&#x27;ll tell you exactly what it was. Fair?&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Accepts the norm without resentment, sets a professional boundary about when it runs, and pre-empts the awkward conversation about activity scores. Confident, not defensive.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">You worked 6 hours but only 4 were genuinely productive</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Billing 6 because you were technically at your desk. Or billing 3 out of guilt and quietly burning out on unpaid time.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">The first is dishonest and eventually noticed. The second is a slower version of the same problem — you&#x27;re training the client to expect an unrealistic output rate that you&#x27;ll have to keep matching forever.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Bill the 4, and get better at the tracking habit. Then in your weekly note: &quot;Tracked 4 hrs this week against the 6 available — the blocker was waiting on the Peterson file. If that&#x27;s a recurring wait, I could use those hours for [the backlog thing] instead.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Honest hours, plus you&#x27;ve turned the gap into a proposal rather than a confession. Clients respect the VA who tells them their hours aren&#x27;t being used well.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Time log that protects you in a dispute</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Keep this even when a client doesn&#x27;t ask. The one time it matters, it really matters.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><div class=\"p-3.5 space-y-3\"><div class=\"overflow-x-auto rounded-lg border border-line\"><table class=\"w-full min-w-[600px] text-[0.8125rem]\"><thead><tr class=\"bg-paper-2\"><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Date</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Start</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">End</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Hrs</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Task</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Category</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Deliverable / evidence</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Billable</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">Mar 4</td><td class=\"px-3 py-2.5 text-ink-2\">06:00</td><td class=\"px-3 py-2.5 text-ink-2\">08:30</td><td class=\"px-3 py-2.5 text-ink-2\">2.5</td><td class=\"px-3 py-2.5 text-ink-2\">Inbox triage</td><td class=\"px-3 py-2.5 text-ink-2\">Admin</td><td class=\"px-3 py-2.5 text-ink-2\">212 → 8 unread, 4 drafts</td><td class=\"px-3 py-2.5 text-ink-2\">Y</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">Mar 4</td><td class=\"px-3 py-2.5 text-ink-2\">08:30</td><td class=\"px-3 py-2.5 text-ink-2\">09:15</td><td class=\"px-3 py-2.5 text-ink-2\">0.75</td><td class=\"px-3 py-2.5 text-ink-2\">Client call</td><td class=\"px-3 py-2.5 text-ink-2\">Meeting</td><td class=\"px-3 py-2.5 text-ink-2\">Notes doc [link]</td><td class=\"px-3 py-2.5 text-ink-2\">Y</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">Mar 4</td><td class=\"px-3 py-2.5 text-ink-2\">09:15</td><td class=\"px-3 py-2.5 text-ink-2\">10:00</td><td class=\"px-3 py-2.5 text-ink-2\">0.75</td><td class=\"px-3 py-2.5 text-ink-2\">Waiting on Peterson file</td><td class=\"px-3 py-2.5 text-ink-2\">Blocked</td><td class=\"px-3 py-2.5 text-ink-2\">Chased 2x, logged</td><td class=\"px-3 py-2.5 text-ink-2\">Y — flagged</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">Mar 4</td><td class=\"px-3 py-2.5 text-ink-2\">10:00</td><td class=\"px-3 py-2.5 text-ink-2\">12:00</td><td class=\"px-3 py-2.5 text-ink-2\">2.0</td><td class=\"px-3 py-2.5 text-ink-2\">Listing launch [address]</td><td class=\"px-3 py-2.5 text-ink-2\">Project</td><td class=\"px-3 py-2.5 text-ink-2\">Checklist complete [link]</td><td class=\"px-3 py-2.5 text-ink-2\">Y</td></tr></tbody></table></div><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">WHY THE COLUMNS MATTER\n• Category lets you show a client where their money actually goes at review time. This is how you argue for a rate change.\n• Deliverable/evidence is your defence. &quot;2.5 hrs on inbox&quot; is a claim; &quot;212 → 8, here&#x27;s the screenshot&quot; is a fact.\n• Blocked time gets logged and FLAGGED, not hidden. Waiting is real work time, but the client needs to know it&#x27;s happening.\n\nROUNDING\nRound to the nearest 15 minutes. Consistently, in both directions.\nDon&#x27;t bill for: your own mistakes and the rework, learning a tool from scratch on their time\nDo bill for: client calls, waiting on them when you can&#x27;t proceed, reading their documentation, admin about their account\n\nMONTHLY, SEND THIS SUMMARY\nTotal: [n] hrs across [n] days\nBy category: Admin [n] · Projects [n] · Meetings [n] · Blocked [n]\nBiggest time sink: [thing] — [n] hrs. [Is this worth automating or dropping?]\nHours I couldn&#x27;t use: [n] — [why]</pre></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Track every hour of your next three days, including job hunting and learning. Then compute what you earned per hour across all of it.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A Toggl or Sheets export plus a three-line note: effective rate, biggest leak, and the one thing you will bill for next time.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 30 min plus three days of logging</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Unpaid categories are logged separately, not hidden</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You included transfer and FX costs in the money side</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The leak you named is specific enough to act on this week</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You did the arithmetic rather than estimating</span></label></li></ul></div>"},{"n":8,"title":"Getting paid without leaking money","outcome":"You can set payment terms, send a clean invoice, and choose the cheapest way to receive money for your client&#x27;s situation.","badges":["Workflow","Tools","2 templates"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Terms first, work second. New clients pay weekly or biweekly, in advance for the first cycle if you can get it. Monthly-in-arrears with a stranger is a loan you did not agree to give.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Wise is usually cheapest when a client pays you directly from a US, UK, EU, or AU bank, because it lands on local rails and converts near the mid-market rate. Payoneer is strong when a platform pays you or the client wants to send to a US-style account. PayPal is the most convenient and the most expensive once the FX markup is counted.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never quote a rate net of fees you have not calculated. On $2,000 a month, a two percent difference is $480 a year.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">An invoice needs a number, a date, the period covered, line items with quantities, the total, the due date, and exactly one payment method. Numbered sequentially, no gaps.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You are self-employed under Philippine rules, which means registering with the BIR, filing, and paying yourself. Many freelancers elect the 8 percent option where eligible instead of graduated rates plus percentage tax. Talk to an accountant once, early, rather than panicking in year three.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Keep client money in an account separate from your spending account. Fifteen minutes of setup, permanent clarity at tax time.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Invoice 0007, and the terms line that prevents arguments</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">INVOICE 0007. Issued 1 September 2026. Period: 16 to 31 August 2026.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Line 1: Inbox and booking support, retainer, 30 hours at $6.00 = $180.00</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Line 2: Approved additional work, quote cleanup project, 4 hours at $6.00 = $24.00 (approved in Slack, 22 Aug)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Total due: $204.00 USD. Due 8 September 2026, net 7.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Pay to: Wise, account details below. Please send in USD; converted amounts short-pay the invoice.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Terms: work pauses on invoices more than 7 days overdue. Additional work outside the retainer is quoted and approved in writing before it starts.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The terms line does the work. It is not aggressive, it is just written down before anyone is annoyed.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Invoice to money in your account</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The 1st of the month, or on project completion. Same day, every time.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Agree payment terms BEFORE the first hour of work</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Amount, date, method, and what happens if it&#x27;s late. Renegotiating terms after you&#x27;ve done the work is a losing position.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Ask for a deposit from any new client</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">50% upfront on projects, or the first month upfront on retainers. Anyone who refuses to pay anything before you start is telling you something.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Invoice on a fixed date, without being asked</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same date monthly. Chasing you for an invoice makes you feel junior; sending it like clockwork makes you feel like a business.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Number every invoice and keep them all</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">INV-2026-001 onwards. You&#x27;ll need this for BIR registration eventually, and for your own sanity when a payment goes missing.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Chase on day 1 late, warmly. Day 7, firmly.</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Most late payments are genuine oversights. A friendly nudge on day one resolves the overwhelming majority.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Stop work at 14 days overdue, as agreed in the contract</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Written in from day one, so enforcing it is just following the agreement rather than a confrontation. The VAs who get burned are the ones who kept working for months.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Starting work with no written agreement because the client seemed nice and you didn&#x27;t want to seem difficult. Nice people also run out of money, restructure, and disappear.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Tool comparison</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Getting paid from the Philippines — what each option really costs</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Over a year, the difference between the best and worst option here is roughly a month&#x27;s salary. This is worth twenty minutes of your attention.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:52rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Tool</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Best for</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Learning curve</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Cost</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Verdict</th></tr></thead><tbody><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Wise</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Direct client invoices. Clients bank-transfer to your local USD details.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — an hour to set up</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free to receive; ~0.4–1% to convert to PHP</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Cheapest for direct clients, by a wide margin. Mid-market rate with the fee shown separately, so nothing is hidden in the exchange rate. Set this up first.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Payoneer</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Marketplace payouts — Upwork, Fiverr, Amazon — where it&#x27;s often the only option.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">1.2–4% to withdraw with conversion; $29.95/yr if you receive under $6,000/yr</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Use it where you must, not by default. The FX markup is buried in the rate, and the annual fee catches low-volume freelancers who never see it coming.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">PayPal</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Small clients who refuse to use anything else.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">~4.4% + fixed fee on international, plus ~4% conversion to PHP</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The most expensive common option — you can lose 6–8% end to end. Accept it to win a client, then move them to Wise in month two.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Direct bank transfer (SWIFT)</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Large one-off payments from corporate clients.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">$15–50 fixed + your bank&#x27;s FX markup</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The fixed fee makes it terrible for small amounts and fine for large ones. Always ask who pays the intermediary bank fees — the answer is usually you, by surprise.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Upwork / marketplace escrow</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Brand new clients you have no reason to trust yet.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">10% platform fee on top of payout fees</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Expensive, but the escrow protection is genuinely worth it for a first contract with a stranger. Think of the 10% as insurance, not as theft.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">GCash / Maya</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Local PH clients only.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Instant</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Low, local</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Fine domestically. Not a solution for international clients — don&#x27;t ask a US client to send to a wallet, it looks unprofessional.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 5 columns and scrolls horizontally on small screens.</span></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Invoice</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Google Docs template, exported as PDF. Never send an editable file.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><div class=\"p-3.5 space-y-3\"><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">INVOICE\n\n[Your full name]\n[Address, city, Philippines]\n[email] | [phone]\n[TIN, if registered]\n\nInvoice #: INV-2026-[001]\nIssue date: [date]\nDue date: [date — state the actual date, never &quot;net 15&quot;]\n\nBILL TO\n[Client business name]\n[Client contact name]\n[Client address]</pre><div class=\"overflow-x-auto rounded-lg border border-line\"><table class=\"w-full min-w-[600px] text-[0.8125rem]\"><thead><tr class=\"bg-paper-2\"><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Description</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Qty</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Rate</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Amount</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">[Service] — [month], per agreement dated [date]</td><td class=\"px-3 py-2.5 text-ink-2\">1</td><td class=\"px-3 py-2.5 text-ink-2\">$[n]</td><td class=\"px-3 py-2.5 text-ink-2\">$[n]</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">[Additional work: what, approved by whom on what date]</td><td class=\"px-3 py-2.5 text-ink-2\">[n] hrs</td><td class=\"px-3 py-2.5 text-ink-2\">$[n]</td><td class=\"px-3 py-2.5 text-ink-2\">$[n]</td></tr></tbody></table></div><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">Subtotal: $[n]\nTOTAL DUE: $[n] USD\n\nPAYMENT\nWise — USD account details:\n  Account holder: [your full legal name, exactly as on your ID]\n  Account number: [n]\n  Routing (ACH): [n]\n  Bank address: [as shown in Wise]\nReference: INV-2026-[001]\n\nPayment due [date]. Work pauses on invoices more than 14 days overdue, as per our agreement.\n\nThank you — [your name]</pre></div></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Payment chase sequence</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Three messages, escalating. Most invoices are paid after the first one.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>DAY 1 LATE — assume it&#x27;s an oversight, because it usually is\n&quot;Hi [name] — invoice INV-[n] for $[n] was due yesterday. Probably just slipped through, no drama. Re-attaching it here. Let me know if you need it in a different format or sent to someone else in accounts.&quot;\n\nDAY 7 — firmer, still warm\n&quot;Hi [name] — following up on INV-[n], $[n], now 7 days overdue.\nIs there anything holding it up on your side? If there&#x27;s a process I should be following, or someone in accounts I should invoice directly, tell me and I&#x27;ll do it that way.\nJust want to keep this simple for both of us.&quot;\n\nDAY 14 — state the consequence, no apology, no threat\n&quot;Hi [name] — INV-[n] is now 14 days overdue.\nAs per our agreement, I&#x27;ll pause work from [date] until it&#x27;s settled. That&#x27;s not me being difficult, it&#x27;s just the term we agreed, and I&#x27;d much rather not.\nCurrent work in progress: [what&#x27;s queued and what stopping affects].\nCan you give me a date it&#x27;ll be paid? If there&#x27;s a cash flow issue, tell me — I&#x27;d rather agree a plan than chase you.&quot;\n\nDAY 21+ — final, and then actually do it\n&quot;Hi [name] — INV-[n] is 21 days overdue and work has been paused since [date].\nI need payment by [date] or I&#x27;ll have to treat the arrangement as ended and pass this to [collections / small claims / the platform&#x27;s dispute process].\nI&#x27;d genuinely rather resolve it. Call me any time on [number].&quot;\n\nTHROUGHOUT\n• Every message in writing, so there&#x27;s a trail\n• Never insult them, never threaten anything you won&#x27;t do\n• Keep working ONLY up to the point you agreed to stop\n• If they go silent for 30 days, treat the money as gone and move on. Chasing costs you more in lost earning time than most invoices are worth.\n\nHOW TO NOT BE HERE AGAIN\n• Deposit upfront from every new client, always\n• First month paid before work begins on a retainer\n• A written agreement, however short\n• Escrow (Upwork) for anyone you don&#x27;t know yet</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build your invoice template in Sheets and issue a fake invoice 0001 to Sortly Home. Then price the same $500 payment through Wise, Payoneer, and PayPal using their live calculators.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: The invoice as a PDF plus a three-row comparison of what actually lands in PHP for each method.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 50 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The invoice has a sequential number and a due date</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Additional work is a separate line with its approval noted</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Your fee comparison uses today&#x27;s real rates, with a screenshot</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You named the method you will default to and why</span></label></li></ul></div>"},{"n":9,"title":"Scams, bad clients, and protecting yourself","outcome":"You can spot the standard scams in under a minute and you know what a bad-but-legal client looks like before you sign.","badges":["Red/green flags","1 template"],"minutes":24,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The absolute rule: money never flows through you. No checks to deposit, no equipment to buy from a supplied vendor, no gift cards, no receiving packages, no using your bank account for client funds. There is no legitimate exception, so you never have to weigh one.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Hired after five minutes of text-only chat, no video, no company you can find, urgent start date: that is not luck, that is the funnel.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Any &quot;job&quot; that asks you to pay for training, a starter kit, or a placement fee is charging you for the privilege of not being hired.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Legal but bad is the more common problem: no contract, vague scope, a client who negotiates every invoice, or one who adds a second boss without adding money.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Get the boring things in writing before day one: scope, hours and time zone, rate, payment schedule, notice period, who owns the work, and what happens to access when it ends.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Reverse-image search the client&#x27;s photo, check the company on LinkedIn, and ask for a short video call. Someone real will find this completely normal.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A message that looks fine and is not</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&quot;Hi! We reviewed your profile and you are hired for the Executive Assistant position, $25/hr, 20 hrs/week, start Monday. First task: we will mail you a check to purchase the office equipment from our approved vendor. Please confirm your full name, address, and bank so payroll can set you up. Interview will be conducted here on chat.&quot;</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Three fatal signals: hired without a call, a check you must deposit, and equipment bought through their vendor.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">One softer signal: a rate well above the market for the described work, which exists to stop you thinking.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Correct action: stop replying, do not send your ID or bank details, report the account, and move on. Do not try to string them along.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Every scam in this market is a variation on getting you to move money or hand over identity documents. Learn the shape once.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A &quot;client&quot; sends you a cheque or overpays and asks for the difference back</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Depositing it, waiting for it to appear in your balance, and sending back the difference via GCash as they asked.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">This is the oldest scam in remote work. The payment reverses days later, the money you sent is gone permanently, and you owe your bank the full amount. There is no version of this that is legitimate.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;I don&#x27;t take overpayments or forward funds — happy to refund the exact overpayment to the original payment method once it&#x27;s fully cleared, but nothing else and nowhere else.&quot; Then stop responding if they push.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">No legitimate employer has ever needed you to receive money and forward it on. Not once. If the request involves you moving money for them, it&#x27;s a scam or it&#x27;s money laundering, and both end badly for you.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A job post or interview asks for money</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Paying a ₱2,000 &quot;registration fee&quot;, &quot;training package&quot;, &quot;equipment deposit&quot; or &quot;background check fee&quot; because the role sounds legitimate and well paid.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Employers pay you. This direction is not negotiable and has no exceptions. The well-paid, professional-sounding wrapper is the whole technique — a scam that looked like a scam wouldn&#x27;t work.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;I don&#x27;t pay to work. If there&#x27;s equipment needed, either you provide it or I use my own. If that&#x27;s a problem, no hard feelings, but I&#x27;ll pass.&quot; Then report the post.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Clean, unembarrassed refusal. You&#x27;ll never regret walking away from a fee request, and there are 2,000 other listings on the board.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">The client wants your passwords and full account access on day one</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Sending your own login credentials, or accepting theirs over Slack, and giving them access to your personal accounts &quot;for verification&quot;.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Sharing credentials breaks most platforms&#x27; terms and destroys the audit trail that protects you. Anyone asking for YOUR personal passwords or your bank login is not hiring you.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;I&#x27;ll need my own staff account with the minimum permissions for what I&#x27;m doing. If you need to share a credential, use a password manager share, not chat. And I&#x27;ll never ask for or give a personal password.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Professional standard, stated calmly as a norm rather than an accusation. Real clients find this reassuring. The ones who push back have told you what you needed to know.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Scam and bad-client screening checklist</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Run this before your first call with any new client. Two minutes, and it will save you months.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>HARD NO — walk away immediately, no exceptions\n[ ] Asks you to pay anything: fee, deposit, training, software, equipment, background check\n[ ] Asks you to receive money and forward it on, in any form\n[ ] Offers a salary wildly above market for basic work ($25/hr for data entry)\n[ ] Hires you without an interview or a single question about your skills\n[ ] Wants to communicate ONLY on Telegram/WhatsApp and won&#x27;t do a video call\n[ ] Asks for your bank login, passwords, or full ID documents before any contract\n[ ] Pressures you to decide in the next hour\n[ ] Sends a cheque or overpays &quot;by accident&quot;\n[ ] Won&#x27;t tell you the company name or give you a website\n[ ] Asks you to buy gift cards or crypto for any reason at all\n\nVERIFY BEFORE YOU COMMIT\n[ ] Company website exists and isn&#x27;t 3 weeks old (check whois)\n[ ] Real LinkedIn presence with real employees who post\n[ ] Search &quot;[company name] scam&quot; and &quot;[company name] reviews&quot;\n[ ] Email domain matches the company — not gmail for a &quot;large agency&quot;\n[ ] Video call happened and their face matched their profile\n[ ] You know the legal entity name and what country they&#x27;re in\n\nSOFT WARNINGS — not scams, but likely to be miserable\n[ ] Can&#x27;t describe the role clearly after two attempts\n[ ] Multiple VAs before you who all &quot;didn&#x27;t work out&quot;\n[ ] Won&#x27;t put anything in writing\n[ ] Scope keeps growing during the interview itself\n[ ] Rate haggling before you&#x27;ve discussed the work\n[ ] Messages you at 2am and expects an answer\n[ ] &quot;We&#x27;re like a family here&quot; plus below-market pay\n[ ] Won&#x27;t agree to a paid trial, only an unpaid one\n\nPAID TRIALS ARE FINE. UNPAID &quot;TESTS&quot; OVER ~1 HOUR ARE NOT.\nA 30-minute sample task is reasonable screening.\nA &quot;test project&quot; that is clearly real client work, unpaid, is theft. Especially if\nseveral candidates got different pieces of the same job.\n\nIF YOU&#x27;VE BEEN SCAMMED\n1. Stop all contact and all work immediately\n2. Screenshot everything before they delete the account\n3. Report: the platform, PNP Anti-Cybercrime Group, DTI if a local business\n4. If bank details were shared: call your bank now, not tomorrow\n5. Tell other VAs. Publicly. The community is the best defence there is.\n6. It is not your fault. These are designed by people who do this full time.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Find three suspicious job posts or messages in the wild, from Facebook groups, Telegram, or your own inbox. Write the specific signals for each.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A short scam-signals sheet you can re-read at 2am when an offer looks too good.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 35 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Each entry names at least two concrete signals, not a vibe</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You separated &quot;scam&quot; from &quot;legal but a bad deal&quot;</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You wrote the exact sentence you would use to decline or disengage</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You listed which documents you will never send before a contract</span></label></li></ul></div>"},{"n":10,"title":"Capstone: proof pack and 30-day plan","outcome":"You have a shareable folder of finished work and a dated plan for the next 30 days, so applying stops being a mood and becomes a routine.","badges":["Workflow","2 templates"],"minutes":45,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Nobody can hire a promise. Assemble the artefacts you already built in this track and put them behind one link.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Label every piece as simulated work for a fictional company. Faking a real client reference is the one lie that ends a career in this market.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Your index page matters more than any single file. Order it the way a client cares: the outcome first, the tooling last.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A 30-day plan needs numbers. Applications per weekday, days you rebuild your top two samples, and one day a week for skills.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Send five tailored applications a day rather than fifty copy-pastes. Reply rate, not volume, is the variable you control.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Set a review date. If 30 days of proper applications gets zero replies, the problem is the lane or the profile, not your worth. Change one variable and run it again.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The folder index a client actually reads</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">1. Two-minute Loom: who I help and what the first week with me looks like.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">2. Inbox and booking SOP for Sortly Home, with a failure branch. Fictional client.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">3. Before and after: a messy enquiry reply rewritten into an approved template.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">4. Quotes tracker sheet, with the formula that flags anything unanswered for 48 hours.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">5. Weekly summary report, one page, the version I would send every Friday.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">6. My working setup: speed test, backup plan, hours, and response windows.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">7. Rate and scope one-pager.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Seven items, all made in one weekend, none requiring a client. This beats a resume in almost every pile it lands in.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">The 30-day plan from finishing this course to first client</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The day you complete the capstone. Start immediately — momentum is most of this.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Days 1–3: build the proof pack</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Three artefacts from this course, one link, one 90-second Loom intro. Not a CV. A link that shows the work.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Days 4–7: fix your profiles</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">OnlineJobs.ph, Upwork and LinkedIn all saying the SAME lane, with the same link. Consistency across three profiles is worth more than one perfect one.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Days 8–21: apply 5 times a day, tracked</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Not 50 in one burst then nothing. Five properly personalised applications daily beats 100 copy-pasted, and it&#x27;s sustainable. Track every one.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Days 8–30: spend 1 hour a day on the lane</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">While applying. Build the dev store, do the keyword map, learn the tool. You&#x27;ll be interviewed on this and it stops the waiting feeling like waiting.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Days 15–30: expect interviews and prepare properly</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Know your rate before you&#x27;re asked. Have three specific stories ready. Test your audio and background before every call.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Day 30: review the funnel, not your feelings</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Applications → replies → interviews → offers. Wherever the number collapses is what to fix. Low replies means your application; low offers after interviews means your interview or your rate.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Waiting until you feel ready. You will not feel ready. Nobody who is now earning $12/hr felt ready when they applied for their first $4/hr job — they applied while feeling unready and got better afterwards.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The proof pack</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">One link you paste into every application, forever. Update it every time you finish something real.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[YOUR NAME] — [Your lane] VA\n[email] | [timezone + the hours you actually commit to] | [phone]\n\nWHAT I DO\n[One sentence, specific. &quot;I run inbox and calendar for founders in US timezones.&quot;]\nNot: &quot;I&#x27;m a hardworking VA who can do anything.&quot;\n\n90-SECOND INTRO: [Loom link]\n(Face, voice, plain background, no script read aloud. Clients hire people they&#x27;ve heard talk.)\n\nWORK SAMPLES\n1. [Artefact name] → [link]\n   What it is: [one line]\n   What it shows: [the skill it proves]\n\n2. [Artefact name] → [link]\n   What it is:\n   What it shows:\n\n3. [Artefact name] → [link]\n   What it is:\n   What it shows:\n\nNote: these are practice scenarios from my training, not paid client work — which means I can show you all of them in full.\n\nTOOLS\n[Only the ones you&#x27;d be happy to be tested on. Cut the rest.]\n\nHOW I WORK\nHours: [specific, in the client&#x27;s timezone]\nResponse time: [what you&#x27;ll actually commit to]\nInternet: [speed] fibre with mobile backup\nReporting: daily EOD summary, weekly written update\n\nRATE\n[$n]/hour, or [$n]/month for [n] hrs/week.\n(Put a number here. &quot;Negotiable&quot; or a blank costs you more than a slightly wrong number.)\n\nAVAILABLE FROM: [date]</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Application tracker</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">A sheet. Not your memory. The funnel numbers tell you what to fix — feelings don&#x27;t.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><div class=\"p-3.5 space-y-3\"><div class=\"overflow-x-auto rounded-lg border border-line\"><table class=\"w-full min-w-[600px] text-[0.8125rem]\"><thead><tr class=\"bg-paper-2\"><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">#</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Date</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Company</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Role</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Source</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Rate posted</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">My ask</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Applied via</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Personalised?</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Reply</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Interview</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Outcome</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Notes</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">1</td><td class=\"px-3 py-2.5 text-ink-2\">Mar 4</td><td class=\"px-3 py-2.5 text-ink-2\">Tidewater</td><td class=\"px-3 py-2.5 text-ink-2\">Ecom VA</td><td class=\"px-3 py-2.5 text-ink-2\">OLJ</td><td class=\"px-3 py-2.5 text-ink-2\">$6/hr</td><td class=\"px-3 py-2.5 text-ink-2\">$7</td><td class=\"px-3 py-2.5 text-ink-2\">Their form</td><td class=\"px-3 py-2.5 text-ink-2\">Y — named their Shopify theme</td><td class=\"px-3 py-2.5 text-ink-2\">Mar 6</td><td class=\"px-3 py-2.5 text-ink-2\">Mar 9</td><td class=\"px-3 py-2.5 text-ink-2\">Offer $6.50</td><td class=\"px-3 py-2.5 text-ink-2\">Took it</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">2</td><td class=\"px-3 py-2.5 text-ink-2\">Mar 4</td><td class=\"px-3 py-2.5 text-ink-2\">[n]</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\">RemoteOK</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr></tbody></table></div><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">REVIEW WEEKLY — these four numbers are the whole picture\nApplications sent: [n]\nReplies: [n] → [n]% ← under 10%? Your APPLICATION is the problem\nInterviews: [n] → [n]% of replies\nOffers: [n] → [n]% of interviews ← low? Your INTERVIEW or your RATE is the problem\n\nWHAT TO FIX, BASED ON WHERE IT BREAKS\nFew replies → your first line is generic, or you&#x27;re applying to the wrong level.\n  Fix: name something specific about THEIR business in sentence one.\nReplies but no interviews → your profile or portfolio isn&#x27;t backing up your pitch.\n  Fix: add the Loom. It converts better than anything else you can do.\nInterviews but no offers → nerves, unclear rate, or you&#x27;re a genuine mismatch.\n  Fix: practise saying your rate out loud until it&#x27;s boring. Ask for feedback from every rejection.\nOffers but all too low → you&#x27;re applying at the bottom of the market.\n  Fix: apply to the top 20% of posts and accept a lower reply rate.\n\nRULE\n5 applications a day, personalised, beats 50 copy-pasted. Every time.\nTrack it or you&#x27;re guessing.</pre></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Assemble the folder, write the index, and build a dated 30-day application plan in a calendar you actually look at.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: One public-view Drive or Notion link plus a 30-day plan with counts and dates.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 90 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every file is clearly labelled as simulated work</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The share link opens in a private browser window</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The plan has a number of applications per day, not a vague intention</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There is a named review date and a stated thing you will change if it fails</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The Loom is under three minutes and you did not read from a script</span></label></li></ul></div>"}],"quiz":[{"q":"A client says \"just use my Gmail password, delegate access is confusing\". What do you do?","options":["Use the password, they insisted","Send the 40-second delegate access steps and offer a Loom","Refuse and withdraw from the role","Use the password but change it every month"],"answer":1,"explain":"Make the safe option easier than the unsafe one. A shared owner login leaves no audit trail, which is a risk to them and an unprovable accusation waiting to happen to you."},{"q":"Your power goes out 10 minutes before a client call. What is the correct first action?","options":["Wait a few minutes to see if it comes back","Message the client from your phone within five minutes with an ETA and what you are switching to","Email an apology after the call time has passed","Join late and explain when someone asks"],"answer":1,"explain":"Clients forgive outages and do not forgive silence. A fast message with a plan reads as competence; a late apology reads as unreliability."},{"q":"You billed 60 hours at $6 and received $351 after fees, but you also spent 18 unbilled hours on onboarding, learning and applications. Your effective rate is closest to:","options":["$$6.00","$$5.85","$$4.50","$$3.90"],"answer":2,"explain":"$$351 divided by 78 total hours is $4.50. The gap between your quoted rate and your effective rate is where beginners quietly lose a third of their income."},{"q":"Which of these is a niche rather than a category?","options":["Experienced virtual assistant, admin and social media","Executive support, flexible, willing to be trained","Inbox and booking support for small home-service businesses in the US","General VA with strong English and attention to detail"],"answer":2,"explain":"It names a buyer and a repeated problem. The other three describe a person, and clients are not shopping for a person, they are shopping for a solved problem."},{"q":"A recruiter offers $25/hr for basic admin, hires you over chat with no call, and will mail a check for you to buy equipment from their vendor. What is your move?","options":["Accept but deposit the check into a separate account to be safe","Negotiate to buy the equipment yourself instead","Stop replying, send no documents, and report the account","Ask for a video call and proceed if they agree"],"answer":2,"explain":"Three fatal signals at once: no call, a check to deposit, and a supplied vendor. There is no version of this that is real, so there is nothing to negotiate or verify."},{"q":"You are two days into a task and realise the client's spreadsheet has two conflicting prices. Best move?","options":["Pick the higher price, it is safer for the client","Pause the affected item, keep working on the rest, and raise it in today's update with what you tried","Wait until the weekly call so you do not seem needy","Guess and note it in the file"],"answer":1,"explain":"Never guess with money and never go silent. Raising it the same day with your attempted resolution attached is exactly the behaviour that turns a beginner into a keeper."}],"glossary":[{"term":"Scope","def":"The specific work you agreed to do. Everything else is a new agreement, not a favour."},{"term":"Retainer","def":"The client pays to reserve a set number of hours per week or month, whether or not they use them all."},{"term":"SOP","def":"Standard operating procedure. A numbered set of steps a stranger could follow to get the same result."},{"term":"Definition of done","def":"The observable condition that means a task is finished. Agreed before you start, not after."},{"term":"Delegate access","def":"Permission to act inside someone's Gmail or calendar without holding their password."},{"term":"Least privilege","def":"Take only the access the work requires. Protects the client and protects you."},{"term":"ID Proof","def":"OnlineJobs.ph's identity trust score. More verified detail raises it, and many employers filter on it."},{"term":"Effective rate","def":"Money received divided by every hour you spent, including unpaid ones. Always lower than your quoted rate."},{"term":"Net 7 / Net 15","def":"The invoice is due 7 or 15 days after issue. State it or you will be paid whenever."},{"term":"Mid-market rate","def":"The real exchange rate between two currencies. Anything worse than it is a fee you are being charged quietly."},{"term":"Activity level","def":"The percentage of tracked time with keyboard or mouse input, reported by tools like Hubstaff and Time Doctor."},{"term":"Idle time","def":"Tracked minutes with no input. Some clients deduct it. Ask before you accept the tracker."},{"term":"Change request","def":"A short written note saying this is new work, here is the time or cost, please approve."},{"term":"Async","def":"Working without live meetings. Requires writing clearly, because you cannot clarify in real time."},{"term":"Onboarding doc","def":"The page you give a new client with your hours, response times, tools, access needs, and outage plan."}]} as DeepCourse;

export default course;
